PRAGMA foreign_keys = ON;
CREATE TABLE user (id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, emailVerified INTEGER NOT NULL DEFAULT 0, image TEXT, createdAt INTEGER NOT NULL, updatedAt INTEGER NOT NULL, role TEXT DEFAULT 'user', banned INTEGER DEFAULT 0, banReason TEXT, banExpires INTEGER);
CREATE TABLE session (id TEXT PRIMARY KEY, expiresAt INTEGER NOT NULL, token TEXT NOT NULL UNIQUE, createdAt INTEGER NOT NULL, updatedAt INTEGER NOT NULL, ipAddress TEXT, userAgent TEXT, userId TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, impersonatedBy TEXT);
CREATE INDEX session_userId_idx ON session(userId);
CREATE TABLE account (id TEXT PRIMARY KEY, accountId TEXT NOT NULL, providerId TEXT NOT NULL, userId TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, accessToken TEXT, refreshToken TEXT, idToken TEXT, accessTokenExpiresAt INTEGER, refreshTokenExpiresAt INTEGER, scope TEXT, password TEXT, createdAt INTEGER NOT NULL, updatedAt INTEGER NOT NULL);
CREATE INDEX account_userId_idx ON account(userId);
CREATE TABLE verification (id TEXT PRIMARY KEY, identifier TEXT NOT NULL, value TEXT NOT NULL, expiresAt INTEGER NOT NULL, createdAt INTEGER NOT NULL, updatedAt INTEGER NOT NULL);
CREATE INDEX verification_identifier_idx ON verification(identifier);
CREATE TABLE rateLimit (id TEXT PRIMARY KEY, key TEXT NOT NULL UNIQUE, count INTEGER NOT NULL, lastRequest INTEGER NOT NULL);
CREATE TABLE members (user_id TEXT PRIMARY KEY REFERENCES user(id), role TEXT NOT NULL CHECK(role IN ('owner','crew')), active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)), created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE UNIQUE INDEX single_owner ON members(role) WHERE role = 'owner';
CREATE TABLE customers (id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL DEFAULT '', phone TEXT NOT NULL DEFAULT '', address TEXT NOT NULL DEFAULT '', notes TEXT NOT NULL DEFAULT '', archived INTEGER NOT NULL DEFAULT 0, version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE jobs (id TEXT PRIMARY KEY, customer_id TEXT NOT NULL REFERENCES customers(id), title TEXT NOT NULL, address TEXT NOT NULL DEFAULT '', status TEXT NOT NULL CHECK(status IN ('lead','scheduled','in_progress','completed','archived')), scheduled_date TEXT NOT NULL DEFAULT '', scope TEXT NOT NULL DEFAULT '', owner_notes TEXT NOT NULL DEFAULT '', quoted_cents INTEGER NOT NULL DEFAULT 0 CHECK(quoted_cents>=0), version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX jobs_customer ON jobs(customer_id);
CREATE TABLE assignments (job_id TEXT NOT NULL REFERENCES jobs(id), user_id TEXT NOT NULL REFERENCES members(user_id), PRIMARY KEY(job_id,user_id));
CREATE INDEX assigned_user ON assignments(user_id,job_id);
CREATE TABLE job_notes (id TEXT PRIMARY KEY, job_id TEXT NOT NULL REFERENCES jobs(id), author_id TEXT NOT NULL REFERENCES members(user_id), body TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE import_batches (id TEXT PRIMARY KEY, source TEXT NOT NULL, kind TEXT NOT NULL, digest TEXT NOT NULL UNIQUE, row_count INTEGER NOT NULL, owner_id TEXT NOT NULL REFERENCES members(user_id), undone INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE expenses (id TEXT PRIMARY KEY, job_id TEXT REFERENCES jobs(id), user_id TEXT NOT NULL REFERENCES members(user_id), date TEXT NOT NULL, vendor TEXT NOT NULL, category TEXT NOT NULL, amount_cents INTEGER NOT NULL CHECK(amount_cents>0), currency TEXT NOT NULL DEFAULT 'USD' CHECK(currency='USD'), notes TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'submitted' CHECK(status IN ('submitted','reviewed','void')), import_id TEXT REFERENCES import_batches(id), fingerprint TEXT UNIQUE, version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX expenses_user ON expenses(user_id,date);
CREATE INDEX expenses_job ON expenses(job_id,date);
CREATE TABLE receipts (id TEXT PRIMARY KEY, expense_id TEXT NOT NULL UNIQUE REFERENCES expenses(id), object_key TEXT NOT NULL UNIQUE, mime TEXT NOT NULL, bytes INTEGER NOT NULL CHECK(bytes>0), uploaded_by TEXT NOT NULL REFERENCES members(user_id), created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE mileage (id TEXT PRIMARY KEY, job_id TEXT REFERENCES jobs(id), user_id TEXT NOT NULL REFERENCES members(user_id), date TEXT NOT NULL, vehicle TEXT NOT NULL, purpose TEXT NOT NULL, start_tenths INTEGER NOT NULL CHECK(start_tenths>=0), end_tenths INTEGER NOT NULL CHECK(end_tenths>=start_tenths), status TEXT NOT NULL DEFAULT 'recorded' CHECK(status IN ('recorded','void')), version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX mileage_user ON mileage(user_id,date);
CREATE TABLE invoices (id TEXT PRIMARY KEY, job_id TEXT REFERENCES jobs(id), number TEXT NOT NULL, customer TEXT NOT NULL, date TEXT NOT NULL, total_cents INTEGER NOT NULL CHECK(total_cents>=0), paid_cents INTEGER NOT NULL DEFAULT 0 CHECK(paid_cents>=0 AND paid_cents<=total_cents), currency TEXT NOT NULL DEFAULT 'USD' CHECK(currency='USD'), status TEXT NOT NULL DEFAULT 'recorded' CHECK(status IN ('recorded','void')), source TEXT NOT NULL DEFAULT 'Manual', import_id TEXT REFERENCES import_batches(id), fingerprint TEXT UNIQUE, version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE activity (id TEXT PRIMARY KEY, actor_id TEXT NOT NULL REFERENCES members(user_id), action TEXT NOT NULL, entity_id TEXT NOT NULL, job_id TEXT REFERENCES jobs(id), created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX activity_job ON activity(job_id,created_at);
CREATE TABLE request_limits (key TEXT PRIMARY KEY, count INTEGER NOT NULL, expires_at INTEGER NOT NULL);
